-- =============================================================================
-- V185 — OCCPL's latest pincode master (Pincode_Master_NEW - SHUBHAM, shared by the user on 2026-11-27).
-- Generated by a script from the sheet, do not edit.
--
-- Updates every global pincode on file that the sheet lists (19127 pincodes; 2 repeated rows take their first):
--   zone             the sheet's Region, written as V174 did (PUNE, X - PUNE, MAHARASHTRA, X - MAHARASHTRA, VIDHARBHA,
--                    REST OF INDIA, NORTH EAST)
--   regional zone    the sheet's zone column (NORTH, SOUTH, EAST, WEST, CENTRAL)
--   Document         serviceable = "Yes", ODA = "Doc Is ODA" 1, TAT = "Doc / nodoc TAT"
--   Surface, Air     serviceable unless "No Service", ODA when "ODA", TAT (none when not serviceable)
--   Air Cargo,       new (V185): serviceable when the cargo ODA column is Y or N ("42" there = no service), ODA when Y,
--   Surface Cargo    TAT from the cargo TAT column (the sheet's 42 filler on no-service rows is dropped)
--   Premium          new (V185): serviceable = "Yes", TAT = "Premium TAT"
-- Serviceable counts: document 11042, surface 17767, air 17828, air cargo 17826,
-- surface cargo 17736, premium 259.
-- Service types: network AIR_CARGO for code AIR_CARGO, SURFACE_CARGO for SURFACE_CARGO, PREMIUM for PREMIUM / PRM, so a
-- booking on them is checked against those columns. pincode_master_sheet is replaced by this sheet, verbatim.
-- The pincode's own serviceable / COD / ODA flags are left as they are; pincodes not on file are not added.
-- =============================================================================

SET @p = UNHEX('00000000000000000000000000000001');

ALTER TABLE master_pincodes
    ADD COLUMN air_cargo_serviceable     BOOLEAN NULL AFTER air_tat_hours,
    ADD COLUMN air_cargo_oda             BOOLEAN NULL AFTER air_cargo_serviceable,
    ADD COLUMN air_cargo_tat_hours       INT     NULL AFTER air_cargo_oda,
    ADD COLUMN surface_cargo_serviceable BOOLEAN NULL AFTER air_cargo_tat_hours,
    ADD COLUMN surface_cargo_oda         BOOLEAN NULL AFTER surface_cargo_serviceable,
    ADD COLUMN surface_cargo_tat_hours   INT     NULL AFTER surface_cargo_oda,
    ADD COLUMN premium_serviceable       BOOLEAN NULL AFTER surface_cargo_tat_hours,
    ADD COLUMN premium_oda               BOOLEAN NULL AFTER premium_serviceable,
    ADD COLUMN premium_tat_hours         INT     NULL AFTER premium_oda;

ALTER TABLE master_service_types MODIFY COLUMN network VARCHAR(20) NULL;
UPDATE master_service_types SET network = 'AIR_CARGO' WHERE code = 'AIR_CARGO' AND deleted = FALSE;
UPDATE master_service_types SET network = 'SURFACE_CARGO' WHERE code = 'SURFACE_CARGO' AND deleted = FALSE;
UPDATE master_service_types SET network = 'PREMIUM' WHERE code IN ('PREMIUM', 'PRM') AND deleted = FALSE;

DROP TABLE IF EXISTS tmp_pin_v185;
CREATE TABLE tmp_pin_v185 (
    pincode CHAR(6) NOT NULL PRIMARY KEY, zone VARCHAR(20) NOT NULL, rz VARCHAR(10) NOT NULL,
    doc_s BOOLEAN NOT NULL, doc_oda BOOLEAN NOT NULL, doc_tat INT NULL,
    sur_s BOOLEAN NOT NULL, sur_oda BOOLEAN NOT NULL, sur_tat INT NULL,
    air_s BOOLEAN NOT NULL, air_oda BOOLEAN NOT NULL, air_tat INT NULL,
    acg_s BOOLEAN NOT NULL, acg_oda BOOLEAN NOT NULL, acg_tat INT NULL,
    scg_s BOOLEAN NOT NULL, scg_oda BOOLEAN NOT NULL, scg_tat INT NULL,
    prm_s BOOLEAN NOT NULL, prm_tat INT NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;





















UPDATE master_pincodes p
JOIN tmp_pin_v185 t ON t.pincode = p.code
LEFT JOIN master_regional_zones z ON z.company_id = @p AND z.code = t.rz AND z.deleted = FALSE
SET p.zone = t.zone, p.regional_zone_id = COALESCE(z.id, p.regional_zone_id),
    p.doc_serviceable = t.doc_s, p.doc_oda = t.doc_oda, p.doc_tat_hours = t.doc_tat,
    p.surface_serviceable = t.sur_s, p.surface_oda = t.sur_oda, p.surface_tat_hours = t.sur_tat,
    p.air_serviceable = t.air_s, p.air_oda = t.air_oda, p.air_tat_hours = t.air_tat,
    p.air_cargo_serviceable = t.acg_s, p.air_cargo_oda = t.acg_oda, p.air_cargo_tat_hours = t.acg_tat,
    p.surface_cargo_serviceable = t.scg_s, p.surface_cargo_oda = t.scg_oda, p.surface_cargo_tat_hours = t.scg_tat,
    p.premium_serviceable = t.prm_s, p.premium_oda = FALSE, p.premium_tat_hours = t.prm_tat,
    p.updated_at = UTC_TIMESTAMP(6), p.version = p.version + 1
WHERE p.company_id = @p AND p.deleted = FALSE;

DROP TABLE tmp_pin_v185;

-- The sheet as given, for Zone Tariff -> Pincode Master Sheet.
ALTER TABLE pincode_master_sheet
    ADD COLUMN air_cargo_tat     VARCHAR(20) NULL,
    ADD COLUMN surface_cargo_tat VARCHAR(20) NULL,
    ADD COLUMN air_cargo_oda     VARCHAR(20) NULL,
    ADD COLUMN surface_cargo_oda VARCHAR(20) NULL,
    ADD COLUMN premium_service   VARCHAR(20) NULL,
    ADD COLUMN premium_tat       VARCHAR(20) NULL;
DELETE FROM pincode_master_sheet;




















